from datetime import timedelta

class OrderPaymentJoin:
    def open(self):
        self.orders = MapState('orders_by_id')
        self.payments = MapState('payments_by_id')

    def process_order(self, order, ctx, out):
        self.orders.put(order['order_id'], order)
        payment = self.payments.get(order['order_id'])
        if payment and abs(order['event_time_ms'] - payment['event_time_ms']) <= 5000 and payment['status'] == 'SETTLED':
            out.emit(join_record(order, payment))
        ctx.register_event_time_timer(order['event_time_ms'] + 5000)

    def process_payment(self, payment, ctx, out):
        self.payments.put(payment['order_id'], payment)
        order = self.orders.get(payment['order_id'])
        if order and abs(order['event_time_ms'] - payment['event_time_ms']) <= 5000 and payment['status'] == 'SETTLED':
            out.emit(join_record(order, payment))
        ctx.register_event_time_timer(payment['event_time_ms'] + 5000)

    def on_timer(self, timestamp, ctx):
        for order_id in ctx.keys_with_expired_interval(timestamp):
            self.orders.remove(order_id)
            self.payments.remove(order_id)

orders = source('orders').assign_timestamps_and_watermarks(max_out_of_orderness_ms=3000)
payments = source('payments').assign_timestamps_and_watermarks(max_out_of_orderness_ms=3000)
joined = orders.key_by(lambda x: x['order_id']).connect(
    payments.key_by(lambda x: x['order_id'])
).process(OrderPaymentJoin(), interval_ms=5000, status='SETTLED')
joined.sink('settled-orders', transactional=True)
checkpoint(enable=True, interval_ms=15000, mode='EXACTLY_ONCE')
